'use strict';
const KEY='operaos-public-sample-v1', MODULES={equipment:'Equipment',attendance:'Attendance',approvals:'Approvals',notifications:'Notifications',reporting:'Reporting'};
const stamp=()=>new Date().toISOString(),uid=()=>crypto.randomUUID(),day=()=>stamp().slice(0,10);
const SAMPLE_PHOTO='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="280" height="200"><rect width="280" height="200" fill="#fff0df"/><circle cx="140" cy="75" r="28" fill="#d28c48"/><path d="M85 150q0-50 55-50t55 50" fill="#d28c48"/><text x="140" y="184" text-anchor="middle" font-family="Arial" font-size="14">SIMULATED DEMO PHOTO</text></svg>');
function base(id,name,type){return {id,name,type,active:true,stage:6,admins:[{id:id+'-admin',name:'Organisation administrator',email:'admin@'+id+'.example'}],modules:{equipment:type==='equipment',attendance:type==='attendance',approvals:type==='equipment',notifications:true,reporting:true},locations:type==='equipment'?['London','Birmingham','Manchester']:['Pakistan','Drivers'],rules:{returnDays:7,followupDays:1,collection:'Collect from your campus equipment desk with your student ID.',returns:'Return to the same campus desk; an administrator must confirm receipt.',dailyHours:8,breakMinutes:0,photoRequired:true},users:[],equipment:[],requests:[],attendance:[],photos:[],logs:[],invites:[],tests:[],onboardingImport:'',status:'Configured workspace'}}
function seed(){let q=base('qahe','QAHE — fictional configuration','equipment'),m=base('mtg','MTG — fictional configuration','attendance');q.admins=[{id:'qahe-admin',name:'Demo QAHE Admin',email:'qahe.admin@example.invalid'}];m.admins=[{id:'mtg-admin',name:'Demo MTG Admin',email:'mtg.admin@example.invalid'}];q.users=[{id:'p1',name:'Demo London Approver',email:'london.approver@example.invalid',kind:'approver',location:'London',active:true},{id:'p2',name:'Demo Birmingham Approver',email:'birmingham.approver@example.invalid',kind:'approver',location:'Birmingham',active:true},{id:'p3',name:'Demo Manchester Approver',email:'manchester.approver@example.invalid',kind:'approver',location:'Manchester',active:true},{id:'DEMO-STUDENT',name:'Fictional Student',email:'student@example.invalid',kind:'student',location:'London',active:true}];q.equipment=[{id:'DEMO-LAPTOP',name:'Demonstration laptop',location:'London',total:3,available:3}];m.users=[{id:'DEMO-STAFF',name:'Fictional Staff Member',email:'staff@example.invalid',kind:'employee',location:'Pakistan',group:'Pakistan staff',active:true},{id:'DEMO-DRIVER',name:'Fictional Driver',email:'driver@example.invalid',kind:'employee',location:'Drivers',group:'Drivers',active:true}];return {version:2,revision:3,orgs:[q,m]}}

let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed();if(db.version!==2||!Array.isArray(db.orgs))db=seed()}catch{db=seed()}
if(db.revision!==3){try{localStorage.setItem(KEY+'-before-portal-update',JSON.stringify(db))}catch{}let defaults=seed();for(let o of db.orgs){let d=defaults.orgs.find(x=>x.id===o.id);if(!d)continue;o.admins=o.admins.map(a=>a.id===o.id+'-admin'?d.admins[0]:a);if(!o.admins.length)o.admins=d.admins;for(let supplied of d.users){let existing=o.users.find(u=>u.id===supplied.id);if(existing)Object.assign(existing,{name:supplied.name,email:supplied.email,location:supplied.location});else o.users.push(supplied)}o.requests=o.requests.filter(r=>!['rq1','rq2'].includes(r.id));o.attendance=o.attendance.filter(r=>!['at1','at2','at3'].includes(r.id));let starterIds=['s1','s2','EMP-PK-001','EMP-PK-002','DRV-001'];o.users=o.users.filter(u=>!starterIds.includes(u.id)||o.requests.some(r=>r.user===u.id)||o.attendance.some(r=>r.user===u.id));o.equipment=o.equipment.filter(e=>!['eq1','eq2','eq3'].includes(e.id)||o.requests.some(r=>r.equipment===e.id));o.logs=o.logs.filter(l=>!l.body.includes('Sample overdue allocation'));o.status='Configured workspace';}db.revision=3;}
for(let o of db.orgs)if(o.id==='mtg')installBundledMTG(o);
let session={role:'owner',org:'qahe',user:'s1',admin:'qahe-admin'},page='dashboard',filter={search:'',status:'',group:'',from:'',to:''},photoDraft=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const current=()=>db.orgs.find(o=>o.id===session.org);const user=(o,id)=>o.users.find(u=>u.id===id);const staffName=(o,id)=>user(o,id)?.name||id;const equipment=(o,id)=>o.equipment.find(e=>e.id===id);const dateText=d=>d?new Date(d).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'—';
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{throw Error('Browser storage is full. Export records and remove stored photos or reset before continuing.')}}
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function guarded(fn){let snapshot=JSON.stringify(db);try{fn();save();render()}catch(e){db=JSON.parse(snapshot);render();notify(e.message)}}
function required(condition,message){if(!condition)throw Error(message)}
function auth(orgId,module,roles){let o=db.orgs.find(x=>x.id===orgId);required(o&&orgId===session.org,'Access denied: organisation mismatch.');required(roles.includes(session.role),'This role is not authorised for this action.');if(session.role==='admin')required(o.admins.some(a=>a.id===session.admin),'Select an authorised organisation administrator.');if(session.role==='user')required(user(o,session.user)?.active,'This user is inactive or unavailable.');if(module){required(o.active,'Activate this organisation before using operational modules.');required(o.modules[module],MODULES[module]+' module is disabled.')}return o}
function email(o,to,subject,body){if(o.modules.notifications)o.logs.unshift({id:uid(),date:stamp(),to,subject,body,mode:'Simulated email'})}
function requestStatus(r){return r.status==='issued'&&r.due<day()?'overdue':r.status}
function calc(a){if(!a.out)return 0;return Math.max(0,(new Date(a.out)-new Date(a.in))/36e5-(a.breakMinutes||0)/60)}
function scopedRequests(o){if(session.role==='owner'||!o.active||!o.modules.equipment)return [];if(session.role==='admin')return o.admins.some(a=>a.id===session.admin)?o.requests:[];if(!user(o,session.user)?.active)return [];let u=user(o,session.user);return o.requests.filter(r=>u?.kind==='approver'?r.approver===u.id:r.user===session.user)}
function scopedAttendance(o){return session.role==='owner'||!o.active||!o.modules.attendance?[]:session.role==='admin'?(o.admins.some(a=>a.id===session.admin)?o.attendance:[]):user(o,session.user)?.active?o.attendance.filter(a=>a.user===session.user):[]}
function requestAction(orgId,rid,action){let o=auth(orgId,'equipment',['admin','user']),r=o.requests.find(r=>r.id===rid);required(r,'Request not found.');let u=user(o,session.user),e=equipment(o,r.equipment);required(e,'Inventory record is missing.');if(['approve','reject'].includes(action)){required(o.modules.approvals,'Approvals module is disabled.');required(session.role==='user'&&u.kind==='approver'&&r.approver===u.id,'Only the assigned campus approver may decide this request.');required(r.status==='pending','This request has already been decided.');if(action==='approve'){required(e.available>=r.qty,'Equipment is unavailable. Approval cannot proceed.');r.status='approved';r.approved=stamp();email(o,user(o,r.user).email,'Request approved',`${r.qty} ${e.name} approved. ${o.rules.collection} Campus: ${r.location}. Due: ${r.due}.`)}else{r.status='rejected';email(o,user(o,r.user).email,'Request rejected',`${e.name} request was rejected by your campus approver.`)}}else if(action==='issue'){required(session.role==='admin','Only organisation administrators can issue equipment.');required(r.status==='approved','Only approved requests can be issued.');required(e.available>=r.qty,'Not enough available inventory.');e.available-=r.qty;r.status='issued';r.issued=stamp();email(o,user(o,r.user).email,'Equipment issued',`${r.qty} ${e.name} issued. ${o.rules.returns} Return by ${r.due}.`)}else if(action==='return'){required(session.role==='admin','Only administrators may confirm physical returns.');required(r.status==='issued','Only issued equipment can be returned.');e.available+=r.qty;required(e.available<=e.total,'Inventory count would exceed total stock.');r.status='returned';r.returned=stamp();email(o,user(o,r.user).email,'Return confirmed',`${r.qty} ${e.name} received at ${r.location}. Inventory updated.`)}else throw Error('Unsupported request action.');return r}
function submitRequest(orgId,input){let o=auth(orgId,'equipment',['user']),u=user(o,session.user);required(u.kind==='student','Only students may submit equipment requests.');required(o.modules.approvals,'Submission paused: approvals must be enabled.');let e=equipment(o,input.equipment),qty=Number(input.qty),approvers=o.users.filter(x=>x.kind==='approver'&&x.active&&x.location===input.location);required(o.locations.includes(input.location),'Select a configured campus.');required(e&&e.location===input.location,'Equipment must belong to the selected campus.');required(Number.isInteger(qty)&&qty>0&&qty<=e.available,'Requested quantity must be positive and within available stock.');required(approvers.length===1,'This campus needs exactly one active authorised approver.');required(input.reason.trim(),'Enter a request purpose.');required(/^\d{4}-\d{2}-\d{2}$/.test(input.due)&&input.due>=day(),'Return date must be today or later.');let r={id:uid(),user:u.id,equipment:e.id,location:input.location,approver:approvers[0].id,qty,reason:input.reason.trim(),due:input.due,status:'pending',created:stamp()};o.requests.push(r);email(o,approvers[0].email,'Campus approval required',`${u.name} requested ${qty} ${e.name} at ${r.location}. Return date: ${r.due}.`);return r}
function followups(o){if(!o.active||!o.modules.equipment||!o.modules.notifications)return 0;let count=0;for(let r of o.requests){let trigger=new Date(r.due+'T00:00:00Z').getTime()-o.rules.followupDays*864e5;if(r.status==='issued'&&Date.now()>=trigger&&r.followed!==r.due){email(o,user(o,r.user)?.email||'archived@example','Scheduled return follow-up',`${equipment(o,r.equipment)?.name} is due ${r.due}${r.due<day()?' (overdue)':''}. ${o.rules.returns}`);r.followed=r.due;count++}}return count}
function attendanceAction(orgId,action,input){let o=auth(orgId,'attendance',['user']),u=user(o,session.user);required(u.kind==='employee','Only employees may record attendance.');let open=o.attendance.find(a=>a.user===u.id&&!a.out);required(action==='in'?!open:!!open,action==='in'?'Duplicate check-in: complete your existing shift first.':'No open shift to check out.');let t=new Date(input.time||stamp());required(Number.isFinite(+t),'Enter a valid time.');required(+t<=Date.now()+60000,'Times cannot be in the future.');if(action==='in'){let last=o.attendance.filter(a=>a.user===u.id&&a.out).sort((a,b)=>new Date(b.out)-new Date(a.out))[0];required(!last||+t>=new Date(last.out),'Check-in cannot overlap a previous shift.')}else required(+t>new Date(open.in),'Check-out must be later than check-in.');required(!o.rules.photoRequired||input.photo,'A check-in/out photo is required. Capture or upload a photo.');let ref=null;if(input.photo){required(o.photos.length<80,'Photo storage limit reached (80). Export records before resetting.');ref=uid();o.photos.push({id:ref,data:input.photo,date:stamp(),user:u.id,simulated:input.photo===SAMPLE_PHOTO})}if(action==='in')o.attendance.push({id:uid(),user:u.id,in:t.toISOString(),out:null,inPhoto:ref,outPhoto:null,breakMinutes:o.rules.breakMinutes,dailyHours:o.rules.dailyHours});else{open.out=t.toISOString();open.outPhoto=ref}email(o,u.email,action==='in'?'Check-in recorded':'Check-out recorded',action==='in'?`${u.id} checked in.`:`${u.id}: ${calc(open).toFixed(4)} working hours recorded.`)}
function validateOrg(o){let errors=[];if(!Object.values(o.modules).some(Boolean))errors.push('Select at least one module.');if(!o.locations.length)errors.push('Add a location.');if(!o.admins.length)errors.push('Add an organisation administrator.');if(o.modules.equipment){if(!o.modules.approvals)errors.push('Equipment requests require approvals.');for(let loc of o.locations)if(o.users.filter(u=>u.active&&u.kind==='approver'&&u.location===loc).length!==1)errors.push(loc+': configure exactly one active approver.')}if(o.modules.attendance&&!(o.rules.dailyHours>0&&o.rules.dailyHours<=24&&o.rules.breakMinutes>=0&&o.rules.breakMinutes<1440))errors.push('Review working-hour rules.');return errors}
function options(list,value){return list.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}
function pill(s){return `<span class="pill ${esc(s)}">${esc(s)}</span>`}function table(head,rows){return rows.length?`<div class="tablewrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching records. This workspace keeps its own data.</div>'}
function stat(items){return `<div class="grid">${items.map(([label,num,sub])=>`<div class="card stat"><span>${label}</span><strong>${num}</strong><span>${sub}</span></div>`).join('')}</div>`}
function card(title,body,action=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}function select(label,name,choices,value){return `<label>${label}<select name="${name}" aria-label="${esc(label)}">${options(choices,value)}</select></label>`}function btn(label,action,id='',extra=''){return `<button data-action="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`}
function nav(){let o=current(),r=session.role,u=user(o,session.user);let list=[['dashboard','Overview','◈']];if(r==='owner')return [...list,['organisations','Organisations','▦'],['onboarding','New organisation','＋'],['history','Historical statistics','▥'],['connections','Connections & status','⇄'],['guide','Setup guide','?'],['development','Development history','⌁']];if(r==='admin'&&o.admins.some(a=>a.id===session.admin)){list.push(['people','People & access','♧']);if(o.active&&o.modules.equipment)list.push(['requests','Equipment requests','↗'],['inventory','Inventory & allocations','▤']);if(o.active&&o.modules.attendance)list.push(['attendance','Attendance','◷']);if(o.active&&o.modules.reporting)list.push(['reports','Reports','▥']);list.push(['settings','Configuration','⚙'],['connections','Data connection','⇄'],['data','CSV data','⇅'])}else if(r==='user'&&u?.active&&o.active){if(o.modules.equipment&&['student','approver'].includes(u.kind))list.push(['requests',u.kind==='approver'?'Assigned approvals':'My equipment','↗']);if(o.modules.attendance&&u.kind==='employee')list.push(['attendance','My attendance','◷'])}if(o.modules.notifications&&r!=='owner'&&(r==='admin'?o.admins.some(a=>a.id===session.admin):u?.active))list.push(['notifications','Notification log','◇']);return [...list,['history','Historical statistics','▥'],['guide','Setup guide','?'],['development','Development history','⌁']]}
function render(){let o=current();if(!o.users.some(u=>u.id===session.user))session.user=o.users.find(u=>u.active)?.id||'';if(!o.admins.some(a=>a.id===session.admin))session.admin=o.admins[0]?.id||'';if(!nav().some(n=>n[0]===page))page='dashboard';let identity=session.role==='owner'?'Demo Platform Owner · Platform administrator':session.role==='admin'?(o.admins.find(a=>a.id===session.admin)?.name||'No administrator'):user(o,session.user)?.name||'No user';$('#app').innerHTML=`<aside><img class="logo" src="logo.png" alt="Opera OS"><small>ONE PRODUCT. YOUR OPERATIONS.</small><nav>${nav().map(([p,l,i])=>`<button class="${page===p?'active':''}" data-page="${p}">${i} &nbsp; ${l}</button>`).join('')}</nav><footer><span class="online-dot"></span> Local storage<br>Administration portal · v3.0<br>Runtime status in Data Connections</footer></aside><div class="main"><header><span class="badge">Opera OS · Administration</span><div class="tools"><select id="org" aria-label="Organisation">${options(db.orgs.map(x=>[x.id,x.name+(x.active?'':' · draft')]),session.org)}</select><select id="portal" aria-label="Portal">${options([['owner','OperaOS Owner Portal'],['admin','Organisation Admin Portal'],['user','User Portal']],session.role)}</select></div></header><main><div class="title"><div><div class="eyebrow">${session.role==='owner'?'OperaOS platform':esc(o.name)+' / workspace'}</div><h1>${nav().find(n=>n[0]===page)?.[1]}</h1><span class="muted">${esc(identity)}</span></div><button id="reset" class="danger">↺ Reset workspace data</button></div>${session.role!=='owner'?`<div class="identity"><label>${session.role==='admin'?'Organisation administrator':'User account'}<select id="identity" aria-label="${session.role==='admin'?'Organisation administrator':'User account'}">${options(session.role==='admin'?o.admins.map(a=>[a.id,a.name]):o.users.map(u=>[u.id,u.name+' · '+u.kind+(u.active?'':' · inactive')]),session.role==='admin'?session.admin:session.user)}</select></label><span>Access mode: local account selection. Secure sign-in has not been connected. Role, organisation and module permissions are checked for each action.</span></div>`:''}${session.role!=='owner'&&!o.active?'<div class="notice">Draft or disabled organisation. Operational modules are unavailable until tested and activated.</div>':''}${content()}</main><div class="bottomnote">Opera OS · Configurable administration · Local storage edition</div></div><dialog id="photoDialog"><button id="closePhoto">Close</button><div id="photoView"></div></dialog>`;bind()}
function requestRows(o){let rows=scopedRequests(o).filter(r=>(!filter.status||requestStatus(r)===filter.status)&&(!filter.group||r.location===filter.group)&&(`${staffName(o,r.user)} ${equipment(o,r.equipment)?.name} ${r.reason}`.toLowerCase().includes(filter.search.toLowerCase())));return table(['Request / student','Campus / approver','Equipment','Return due','Status','Actions'],rows.slice().reverse().map(r=>{let actions='',u=user(o,session.user);if(session.role==='user'&&u?.kind==='approver'&&r.status==='pending'&&r.approver===u.id&&o.modules.approvals)actions=btn('Approve','approve',r.id)+btn('Reject','reject',r.id);if(session.role==='admin'){if(r.status==='approved')actions=btn('Issue equipment','issue',r.id);if(r.status==='issued')actions=btn('Confirm return','return',r.id)}return [`<b>${esc(staffName(o,r.user))}</b><br><span class="muted">${esc(r.reason)}<br>${dateText(r.created)}</span>`,`${esc(r.location)}<br><span class="muted">${esc(staffName(o,r.approver))}</span>`,`${esc(equipment(o,r.equipment)?.name)} × ${r.qty}`,`${r.due}<br>${r.returned?'<span class="muted">Returned '+dateText(r.returned)+'</span>':''}`,pill(requestStatus(r)),actions||'—']}))}
function filters(kind){let o=current();return `<form id="filters" class="form filterform">${field('Search','search',filter.search,'search','placeholder="Name, equipment or ID"')}${select(kind==='requests'?'Campus':'Reporting group','group',['',...(kind==='requests'?o.locations:['Pakistan staff','Drivers'])],filter.group)}${kind==='requests'?select('Request status','status',['','pending','approved','rejected','issued','returned','overdue'],filter.status):''}${kind==='attendance'?field('From (UTC)','from',filter.from,'date')+field('To (UTC)','to',filter.to,'date'):''}<button>Apply filters</button><button type="button" data-action="clearfilters">Clear</button></form>`}
function filteredAttendance(o){return scopedAttendance(o).filter(a=>{let u=user(o,a.user);return (!filter.search||`${a.user} ${u?.name}`.toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.group||u?.group===filter.group)&&(!filter.from||a.in.slice(0,10)>=filter.from)&&(!filter.to||a.in.slice(0,10)<=filter.to)})}
function photoButton(ref){return ref?btn(ref==='sample'?'Placeholder photo':'View photo','photo',ref):'<span class="muted">Missing</span>'}
function attendanceRows(o){return table(['Employee / group','Date (UTC)','Check-in','Check-out','Photos','Working hours'],filteredAttendance(o).slice().reverse().map(a=>[`<b>${esc(staffName(o,a.user))}</b><br><span class="muted">${esc(a.user)} · ${esc(user(o,a.user)?.group)}</span>`,a.in.slice(0,10),dateText(a.in),a.out?dateText(a.out):pill(a.in.slice(0,10)<day()?'missing checkout':'open shift'),`${photoButton(a.inPhoto)} ${photoButton(a.outPhoto)}`,a.out?calc(a).toFixed(4):'—']))}
function historical(){return card('Historical imports','<p>No client history is included in this repository. Uploaded history stays labelled and separate from connected demonstration records.</p>')}
function content(){let o=current(),u=user(o,session.user),owner=session.role==='owner',equipmentView=o.modules.equipment&&(!o.modules.attendance||o.type==='equipment'||u?.kind==='student'||u?.kind==='approver');if(page==='history')return historical();if(page==='guide')return setupGuide();if(page==='development')return card('Actual dated development records',`<p><b>11 October 2026 · v1.0</b><br>Created the original fictional two-organisation browser demo with roles, inventory approvals, attendance, persistence and CSV support.</p><p><b>11 October 2026 · v2.0</b><br>Updated to the supplied Opera OS logo and orange, black and white design. Added QAHE and MTG sample configurations, campus-scoped approval, issue/return inventory, follow-ups, photo references, group reports, configurable rules, onboarding and application-level permission checks.</p><p><b>11 October 2026 · v2.1</b><br>Applied supplied campus approver and organisation administrator details, updated portal presentation, removed starter operational records, and added the complete organisation setup guide.</p><p><b>11 October 2026 · v2.2</b><br>Imported runtime adapters and labelled sample transactions, added historical CSV export and completed a labelled fictional check-in/out test.</p><p><b>12 October 2026 · v3.0</b><br>Added encrypted backend connection settings, Apps Script/Power Automate adapters, runtime activity and connected-record counts. Supplied MTG endpoint has no doPost; real transaction verification remains pending.<br><br>Historical deployment figures are user-supplied records, not development events. No earlier development dates have been invented.</p>`);
if(page==='dashboard'&&owner)return `<div class="welcome"><div class="eyebrow">OperaOS Owner Portal</div><h2>One platform. Configured for every organisation.</h2><p>Welcome, Demo Platform Owner. Manage workspaces, administrators and capabilities from one place. The overview shows configuration and aggregate workspace usage; private employee records are excluded.</p></div>${stat([['Organisations',db.orgs.length,'Independent configurations'],['Activated organisations',db.orgs.filter(x=>x.active).length,'Local configuration state'],['Enabled modules',db.orgs.reduce((n,x)=>n+Object.values(x.modules).filter(Boolean).length,0),'Across organisations'],['Selected connection',typeof runtime!=='undefined'&&runtime.org===session.org?runtime.connection.status:'Loading','Runtime status, not historical totals']])}${card('Organisation workspaces',table(['Organisation','Enabled capabilities','Workspace activity','Configuration'],db.orgs.map(x=>[`<b>${esc(x.name)}</b><br><span class="muted">Configuration · ${esc(x.type)}</span>`,`<div class="modules">${Object.entries(MODULES).filter(([k])=>x.modules[k]).map(([,l])=>pill(l)).join('')}</div>`,`${x.requests.length} requests · ${x.attendance.length} attendance entries`,`${pill(x.active?'activated':'draft')}<br>${btn('Configure','configure',x.id)}`])),btn('＋ New organisation','neworg'))}<div class="split">${card('Platform administrator','<div class="profile"><span class="avatar">DO</span><div><h2>Demo Platform Owner</h2><p>OperaOS platform administrator<br><span class="muted">Owner-level configuration access</span></p></div></div>')}${card('Deployment & data status','<div class="module">Application runtime <b>Local portal with optional backend</b></div><div class="module">Hosted deployment <b>Not verified</b></div><div class="module">Test integrations <b>See Data Connections</b></div>')}</div>`;
if(page==='dashboard'){let rs=scopedRequests(o),as=scopedAttendance(o);return historicalImportReport(o,true)+`<div class="welcome"><div class="eyebrow">${esc(o.name)} / WORKSPACE</div><h2>${equipmentView?'Equipment from request to return.':'A clear record of the working day.'}</h2><p>${equipmentView?'Campus-specific approval, controlled issue and confirmed returns.':'Check-in/out photos, configurable working hours and separate staff/driver reports.'} Connected services and deployment status are available in Data connection.</p></div>${stat(equipmentView?[['Requests',o.modules.equipment?rs.length:'—','Workspace records'],['Awaiting approval',o.modules.equipment?rs.filter(r=>r.status==='pending').length:'—','Campus-routed decisions'],['Issued / overdue',o.modules.equipment?rs.filter(r=>r.status==='issued').length:'—','Stock currently allocated'],['Available units',o.modules.equipment?o.equipment.reduce((n,e)=>n+e.available,0):'—','Inventory updates on issue/return']]:[['New portal entries',o.modules.attendance?as.length:'—','Separate from imported history'],['New completed shifts',o.modules.attendance?as.filter(a=>calc(a)>0).length:'—','Includes labelled dummy test'],['Missing check-outs',o.modules.attendance?as.filter(a=>!a.out&&a.in.slice(0,10)<day()).length:'—','Needs review'],['Working hours',o.modules.attendance?as.reduce((n,a)=>n+calc(a),0).toFixed(2):'—','Completed sessions']])}<div class="split">${card(equipmentView?'Equipment activity':'Attendance activity',o.active&&(equipmentView?o.modules.equipment:o.modules.attendance)?(equipmentView?requestRows(o):attendanceRows(o)):'<div class="empty">Operational module disabled.</div>')}${card('Enabled modules',Object.entries(MODULES).map(([k,l])=>`<div class="module"><span>${l}</span>${pill(o.modules[k]?'enabled':'disabled')}</div>`).join('')+'<p class="muted">Module configuration changes available actions. Workspace counters remain separate from reported historical totals.</p>')}</div>`}
if(page==='organisations')return db.orgs.map(x=>card(esc(x.name),`<p>Configuration · ${esc(x.status)} · ${x.admins.length} administrator(s)</p><form data-form="modules" data-org="${x.id}" class="form">${Object.entries(MODULES).map(([k,l])=>`<label class="checkbox"><input name="${k}" type="checkbox" ${x.modules[k]?'checked':''}>${l}</label>`).join('')}<button class="primary">Save modules</button></form><br>${btn('Configure organisation','configure',x.id)} ${btn(x.active?'Disable workspace':'Test & activate','toggleOrg',x.id)} ${btn('Continue onboarding','onboard',x.id)}<p class="muted">Records are retained when modules are disabled. Equipment submission requires approvals. Notifications disabled means no new simulated emails.</p>`)).join('');
if(page==='onboarding')return onboarding();
if(page==='people')return (o.id==='mtg'?card('Fictional workflow test','<p>Historical records are kept separate. Add a clearly labelled dummy employee to demonstrate check-in/out with calculated hours.</p>'+btn('Add fictional test employee','dummyEmployee')):'')+card('Users & access',table(['User / ID','Role','Location / group','Status','Action'],o.users.map(s=>[`<b>${esc(s.name)}</b><br><span class="muted">${esc(s.id)} · ${esc(s.email)}</span>`,esc(s.kind),`${esc(s.location)}<br>${esc(s.group||'')}`,pill(s.active?'active':'inactive'),btn(s.active?'Deactivate':'Activate','toggleUser',s.id)])))+card('Add user',userForm(o,'user'))+card('Organisation administrators',table(['Name','Email'],o.admins.map(a=>[esc(a.name),esc(a.email)]))+'<p class="muted">Organisation administrators are managed in the Owner Portal.</p>');
if(page==='requests'){let form='';if(session.role==='user'&&u?.kind==='student'){let due=new Date(Date.now()+o.rules.returnDays*864e5).toISOString().slice(0,10);form=card('New equipment request',`<p>${esc(o.rules.collection)}</p><form data-form="request" class="form">${select('City / campus','location',o.locations,u.location)}${select('Equipment','equipment',o.equipment.map(e=>[e.id,e.name+' · '+e.location+' ('+e.available+' available)']))}${field('Quantity','qty',1,'number','min="1" max="999" required')}${field('Purpose','reason','','text','maxlength="200" required')}${field('Return date','due',due,'date','required')}<button class="primary">Submit request</button></form><p class="muted">The selected campus determines the authorised approver. Equipment choices must match the campus.</p>`)}return form+card(session.role==='user'&&u?.kind==='approver'?'Requests assigned to you':'Requests & returns',filters('requests')+requestRows(o),session.role==='admin'&&o.modules.notifications?btn('Run due follow-ups','followups'):'')}
if(page==='inventory')return card('Inventory by campus',table(['Equipment','Campus','Total','Available','Allocated','Action'],o.equipment.map(e=>[esc(e.name),esc(e.location),e.total,e.available,e.total-e.available,`<form data-form="stock" class="stockform"><input name="id" type="hidden" value="${e.id}"><input name="total" type="number" min="${e.total-e.available}" max="100000" value="${e.total}" aria-label="New total units for ${esc(e.name)}" required><button>Adjust stock</button></form>`])))+card('Add inventory',`<form data-form="equipment" class="form">${field('Equipment name','name','','text','required maxlength="70"')}${select('Campus','location',o.locations)}${field('Total units','total',1,'number','min="1" max="100000" required')}<button class="primary">Add equipment</button></form>`)+card('Allocations & returns',requestRows(o));
if(page==='attendance'){let open=o.attendance.find(a=>a.user===session.user&&!a.out);let form=session.role==='user'?card(open?'Complete your shift':'Start your shift',`<div class="clock">${open?Math.max(0,(Date.now()-new Date(open.in))/36e5).toFixed(2):'0.00'} <span class="muted">elapsed hours</span></div><p>${open?'Current check-in: '+dateText(open.in):'Photo capture supports your device camera or a local image upload.'}</p><form data-form="clock" class="form">${field('Event time (local)','time','','datetime-local')}${u?.dummy?btn('Use simulated photo — dummy data','samplePhoto'):''}<label>Capture / upload photo<input id="photoFile" type="file" accept="image/*" capture="user"></label><button class="primary">${open?'Check out':'Check in'}</button></form><div id="photoPreview">${photoDraft?'<img src="'+esc(photoDraft)+'" alt="Pending attendance photo"><span>Photo ready'+(photoDraft===SAMPLE_PHOTO?' · Simulated photo':' · Local capture/upload')+'</span>':'<p class="muted">No photo selected.</p>'}</div><p class="muted">Blank time uses the current timestamp. ${o.rules.photoRequired?'Photos are required.':'Photos are optional.'} Break deduction: ${o.rules.breakMinutes} minutes. Rule values are saved with each shift.</p>`):'';return historicalImportReport(o,true)+form+card('Attendance history',filters('attendance')+attendanceRows(o),session.role==='admin'?btn('Export attendance CSV','export','attendance'):'')+(session.role==='admin'?card('Resolve missing check-out',`<p>Enter the recorded end time for an incomplete shift. Existing photo evidence is retained; a missing end photo is explicitly recorded as missing.</p><form data-form="resolve" class="form">${select('Open shift','shift',o.attendance.filter(a=>!a.out).map(a=>[a.id,staffName(o,a.user)+' · '+dateText(a.in)]))}${field('Recorded check-out','out','','datetime-local','required')}<button class="primary">Complete record</button></form>`):'')}
if(page==='reports')return reports(o);
if(page==='settings')return settings(o,false);
if(page==='connections')return card('Data connection settings',`<div class="connection"><span class="dot">⇄</span><div><h2>Persistent local storage</h2><p>Connected to this browser’s localStorage. Each organisation has separate records and settings.</p></div>${pill('local only')}</div>${table(['Connection','Status'],[['Excel / Google Sheets synchronisation','No live connection — CSV import/export only'],['Existing QAHE deployment','Not connected'],['Existing Mobile Tyre Giant deployment','Not connected'],['Email delivery','Simulated notification log only'],['Photo storage','Local storage · no external upload'],['Hosting / deployment','Local app available; hosted publication not verified']])}<p class="muted">A production connection requires a separately implemented and tested integration. No synchronisation is implied by CSV compatibility.</p>`);
if(page==='notifications'){let logs=o.logs.filter(l=>session.role==='admin'||l.to===u?.email);return `<div class="notice">Simulated email — no outgoing emails are sent. Due follow-ups are processed while the portal is open, at refresh and via the admin’s “Run due follow-ups” action. No background server scheduler exists.</div>`+card('Notification log',logs.length?logs.map(l=>`<div class="activity"><span class="dot">✉</span><div><b>${esc(l.subject)}</b><p>${esc(l.body)}</p><small>Simulated email · ${esc(l.to)} · ${dateText(l.date)}</small></div></div>`).join(''):'<div class="empty">No simulated emails for this account.</div>')}
if(page==='data')return mtgImportScreen(o)+csvScreen(o);
return '<div class="empty">This page is unavailable for your access level.</div>'}
function userForm(o,formName){return `<form data-form="${formName}" class="form">${field('Name','name','','text','required maxlength="70"')}${field('Employee / user ID (optional)','id','','text','maxlength="70"')}${field('Email','email','','email','required')}${select('Role','kind',[...(o.modules.attendance?['employee']:[]),...(o.modules.equipment?['student','approver']:[])])}${select('Location','location',o.locations)}${select('Reporting group','group',['Pakistan staff','Drivers'])}<button class="primary">Add user</button></form>`}
function settings(o,owner){return card('Locations, roles & operational rules',`<form data-form="settings" data-org="${o.id}" class="form">${field('Organisation name','name',o.name,'text','required maxlength="80"')}${field('Locations / campuses (comma separated)','locations',o.locations.join(', '),'text','required')}${o.modules.equipment?field('Default return days','returnDays',o.rules.returnDays,'number','min="1" max="365" required'):''}${o.modules.equipment?field('Follow-up days before due','followupDays',o.rules.followupDays,'number','min="0" max="30" required'):''}${o.modules.equipment?field('Collection instructions','collection',o.rules.collection,'text','required maxlength="500"'):''}${o.modules.equipment?field('Return instructions','returns',o.rules.returns,'text','required maxlength="500"'):''}${o.modules.attendance?field('Regular daily hours','dailyHours',o.rules.dailyHours,'number','min="0.5" max="24" step="0.5" required'):''}${o.modules.attendance?field('Break deduction (minutes)','breakMinutes',o.rules.breakMinutes,'number','min="0" max="480" required'):''}${o.modules.attendance?`<label class="checkbox"><input name="photoRequired" type="checkbox" ${o.rules.photoRequired?'checked':''}>Require check-in/out photos</label>`:''}<button class="primary">Save configuration</button></form><p class="muted">${o.modules.equipment?'New requests use the configured campus approver. Existing assignments remain fixed. ':''}${o.modules.attendance?'Attendance rules are snapshotted at check-in, so changes do not rewrite old hours.':''}</p>`)+(o.modules.equipment?card('Campus-authorised approvers',table(['Name','Email','Assigned campus','Status'],o.users.filter(u=>u.kind==='approver').map(u=>[esc(u.name),esc(u.email),esc(u.location),pill(u.active?'active':'inactive')]))+`<form data-form="route" data-org="${o.id}" class="form">${select('Approver','user',o.users.filter(u=>u.kind==='approver').map(u=>[u.id,u.name]))}${select('Assign campus','location',o.locations)}<button>Save approver route</button></form><p class="muted">Exactly one active approver per campus is required. Add approvers in People & access or onboarding.</p>`):'')+(owner?card('Organisation administrators',table(['Name','Email','Action'],o.admins.map(a=>[esc(a.name),esc(a.email),btn('Remove administrator','removeAdmin',a.id,`data-org="${o.id}"`)]))+`<form data-form="admin" data-org="${o.id}" class="form">${field('Name','name','','text','required')}${field('Email','email','','email','required')}<button>Add administrator</button></form>`):'')}
function reports(o){let as=filteredAttendance(o),rs=scopedRequests(o);return historicalImportReport(o)+`<div class="notice">Workspace reports — historical supplied deployment totals are displayed separately. Working hours = elapsed shift hours − configured break deduction; minimum zero. Overtime = working hours above the saved daily rule.</div>${o.modules.attendance?card('Attendance & working hours',filters('attendance')+stat([['Completed shifts',as.filter(a=>calc(a)>0).length,'Hours > 0'],['Working hours',as.reduce((n,a)=>n+calc(a),0).toFixed(4),'Completed records'],['Driver overtime',as.filter(a=>user(o,a.user)?.group==='Drivers').reduce((n,a)=>n+Math.max(0,calc(a)-a.dailyHours),0).toFixed(4),'Saved daily thresholds'],['Incomplete records',as.filter(a=>!a.out||!a.inPhoto||!a.outPhoto).length,'Missing time or photo evidence']])+table(['Group / employee','ID','Completed shifts','Hours','Overtime'],o.users.filter(u=>u.kind==='employee'&&(!filter.group||u.group===filter.group)&&(!filter.search||`${u.id} ${u.name}`.toLowerCase().includes(filter.search.toLowerCase()))).map(u=>{let rows=as.filter(a=>a.user===u.id);return [`${esc(u.group)} / ${esc(u.name)}`,esc(u.id),rows.filter(a=>calc(a)>0).length,rows.reduce((n,a)=>n+calc(a),0).toFixed(4),rows.reduce((n,a)=>n+Math.max(0,calc(a)-a.dailyHours),0).toFixed(4)]})),btn('Export hours CSV','export','hours')):''}${o.modules.equipment?card('Equipment transaction report',filters('requests')+requestRows(o),btn('Export requests CSV','export','requests')):''}${!o.modules.equipment&&!o.modules.attendance?card('Reports','Enable equipment or attendance to generate operational reports.'):''}`}
function csvScreen(o){return card('Spreadsheet-compatible CSV',`<p>CSV files work with Excel and Google Sheets. Import appends validated records only to ${esc(o.name)}. No live synchronisation exists.</p><div class="tools">${session.role==='owner'?'':btn('Export users','export','users')}${session.role!=='owner'&&o.modules.equipment?btn('Export inventory','export','equipment')+btn('Export requests','export','requests'):''}${session.role!=='owner'&&o.modules.attendance?btn('Export attendance','export','attendance')+btn('Export hours','export','hours'):''}${session.role!=='owner'&&o.modules.notifications?btn('Export notification log','export','logs'):''}</div><br><form data-form="import" class="form">${select('Import type','type',[['users','Users'],...(o.modules.equipment?[['equipment','Inventory']]:[])])}<label>CSV file<input name="file" type="file" accept=".csv,text/csv" required></label><button class="primary">Validate & import</button></form><p class="muted">Users headers: id,name,email,kind,location,group,active. Inventory headers: name,location,total,available. IDs may be blank to generate one. All rows are validated before import; duplicates, invalid counts and unknown locations are rejected. Maximum 1,000 rows / 2 MB. Quoted fields supported. Exported CSV neutralises spreadsheet formula prefixes.</p>`)}
function onboarding(){let o=current(),stage=o.stage||1;return `<div class="steps">${['Create','Modules','Configure','Records','Invite','Test & activate'].map((x,i)=>`<span class="${stage===i+1?'current':''}">${i+1}. ${x}</span>`).join('')}</div>${stage===1?card('1. Create organisation',`<form data-form="create" class="form">${field('Organisation name','name','','text','required maxlength="80"')}${select('Starting configuration','type',[['equipment','Equipment management'],['attendance','Workforce attendance']])}<button class="primary">Create separate workspace</button></form>`):''}${stage===2?card('2. Select modules',`<p>${esc(o.name)} · draft organisation. Select the required capabilities.</p><form data-form="onboardModules" class="form">${Object.entries(MODULES).map(([k,l])=>`<label class="checkbox"><input name="${k}" type="checkbox" ${o.modules[k]?'checked':''}>${l}</label>`).join('')}<button class="primary">Save & continue</button></form>`):''}${stage===3?settings(o,true)+card('3. Configure users and approvers',userForm(o,'onboardUser')+table(['Name','Role','Campus'],o.users.map(u=>[esc(u.name),esc(u.kind),esc(u.location)]))+btn('Configuration ready → records','nextStage')):''}${stage===4?csvScreen(o)+card('4. Import records or start empty',`<p>${o.users.length} user records · ${o.equipment.length} inventory records. Imports are separate from all other organisations.</p>${btn('Continue with current / empty records','nextStage')}`):''}${stage===5?card('5. Invite users',`<p>Invitations are simulated and never send email. Add users first or invite an administrator email.</p><form data-form="invite" class="form">${field('Invitation email','email','','email','required')}<button class="primary">Simulate invitation</button></form><br>${table(['Recipient','Time','Mode'],o.invites.map(x=>[esc(x.email),dateText(x.date),'Simulated invitation']))}${btn('Continue to testing','nextStage')}`):''}${stage===6?card('6. Test & activate configuration',`<p>${esc(o.name)} · ${o.active?'activated':'draft'} · ${o.users.length} users · ${o.equipment.length} equipment types</p>${validateOrg(o).length?'<div class="notice">'+validateOrg(o).map(esc).join('<br>')+'</div>':'<p>Configuration checks are ready to run. Empty operational records are supported.</p>'}${btn('Run configuration test','testOrg')} ${btn('Activate organisation','activateOrg')}<br><br>${table(['Test timestamp','Result'],o.tests.map(t=>[dateText(t.date),esc(t.result)]))}<p class="muted">Activation checks modules, locations, administrators, campus approvers and working-hour rules. It does not verify external integrations.</p>`):''}${stage>1?`<div class="tools">${btn('← Previous step','prevStage')}${btn('Return to owner overview','ownerOverview')}</div>`:''}`}
function addUser(o,f){let kind=f.kind,location=f.location,id=f.id?.trim()||uid();required(['student','approver','employee'].includes(kind),'Invalid user role.');required(o.locations.includes(location),'Unknown location.');required(f.name.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email),'Name and valid email required.');required(!o.users.some(u=>u.id===id||u.email.toLowerCase()===f.email.toLowerCase()),'Duplicate ID or email.');if(kind==='approver')required(!o.users.some(u=>u.kind==='approver'&&u.location===location&&u.active),'This campus already has an active approver.');o.users.push({id,name:f.name.trim(),email:f.email.trim(),kind,location,group:kind==='employee'?f.group:'',active:true})}
function setRules(o,f){let locations=[...new Set(f.locations.split(',').map(x=>x.trim()).filter(Boolean))];required(f.name.trim()&&locations.length,'Name and at least one location are required.');required(o.users.every(u=>locations.includes(u.location))&&o.equipment.every(e=>locations.includes(e.location)),'A location used by existing users or inventory cannot be removed.');let dailyHours=Number(f.dailyHours??o.rules.dailyHours),breakMinutes=Number(f.breakMinutes??o.rules.breakMinutes),returnDays=Number(f.returnDays??o.rules.returnDays),followupDays=Number(f.followupDays??o.rules.followupDays);required(dailyHours>0&&dailyHours<=24&&Number.isInteger(breakMinutes)&&breakMinutes>=0&&breakMinutes<=480,'Invalid working-hour rules.');required(Number.isInteger(returnDays)&&returnDays>=1&&returnDays<=365&&Number.isInteger(followupDays)&&followupDays>=0&&followupDays<=30,'Invalid return rules.');o.name=f.name.trim();o.locations=locations;o.rules={dailyHours,breakMinutes,returnDays,followupDays,collection:(f.collection??o.rules.collection).trim(),returns:(f.returns??o.rules.returns).trim(),photoRequired:o.modules.attendance?f.photoRequired==='on':o.rules.photoRequired}}
function action(name,id,targetOrg){if(['approve','reject','issue','return'].includes(name)){requestAction(session.org,id,name);notify('Request '+name+' completed.');return}let o=current();if(name==='neworg'){auth(session.org,null,['owner']);let draft=db.orgs.find(x=>x.stage===1&&!x.active);if(!draft){draft=base(uid(),'New organisation','equipment');draft.active=false;draft.stage=1;draft.admins=[];draft.locations=[];db.orgs.push(draft)}session.org=draft.id;page='onboarding';return}if(name==='configure'){auth(session.org,null,['owner']);session.org=id;page='settingsOwner';return}if(name==='onboard'){auth(session.org,null,['owner']);session.org=id;page='onboarding';return}if(name==='toggleOrg'){auth(session.org,null,['owner']);let x=db.orgs.find(x=>x.id===id);required(x,'Organisation unavailable.');if(x.active)x.active=false;else{let errors=validateOrg(x);required(!errors.length,errors.join(' '));x.tests.push({date:stamp(),result:'Passed activation checks'});x.active=true}notify('Workspace state updated.');return}if(name==='clearfilters'){filter={search:'',status:'',group:'',from:'',to:''};return}if(name==='toggleUser'){o=auth(session.org,null,['admin']);let u=user(o,id);required(u,'User not found.');if(u.active&&u.kind==='approver')required(!o.requests.some(r=>r.approver===id&&r.status==='pending'),'Reassign or decide pending requests before deactivating an approver.');if(!u.active&&u.kind==='approver')required(!o.users.some(x=>x.id!==u.id&&x.active&&x.kind==='approver'&&x.location===u.location),'Campus already has an active approver.');u.active=!u.active;notify('User status saved.');return}if(name==='followups'){o=auth(session.org,'notifications',['admin']);required(o.modules.equipment,'Equipment module is disabled.');notify(followups(o)+' due follow-up(s) logged.');return}if(name==='samplePhoto'){auth(session.org,'attendance',['user']);photoDraft=SAMPLE_PHOTO;notify('Simulated photo selected.');return}if(name==='dummyEmployee'){o=auth(session.org,'attendance',['admin']);required(o.id==='mtg','MTG only.');if(!user(o,'TEST-MTG'))o.users.push({id:'TEST-MTG',name:'Fictional Test Employee — dummy data',email:'test.employee@example.invalid',kind:'employee',group:'Pakistan staff',location:'Pakistan',active:true,dummy:true});notify('Clearly labelled fictional test employee added.');return}if(name==='photo'){o=auth(session.org,'attendance',['admin','user']);let photo=id==='sample'?{data:SAMPLE_PHOTO,simulated:true}:o.photos.find(p=>p.id===id);required(photo,'Photo reference unavailable.');if(session.role==='user')required(id==='sample'||photo.user===session.user,'You may view only your own photos.');setTimeout(()=>{$('#photoView').innerHTML=`<h2>${photo.simulated?'Placeholder photo':'Local attendance photo'}</h2><img src="${esc(photo.data)}" alt="Attendance evidence"><p class="muted">Reference: ${esc(id)} · Stored locally</p>`;$('#photoDialog').showModal()},0);return}if(name==='export'){exportCSV(id);return}if(name==='removeAdmin'){auth(session.org,null,['owner']);let x=db.orgs.find(x=>x.id===(targetOrg||session.org));required(x.admins.length>1,'Keep at least one administrator.');x.admins=x.admins.filter(a=>a.id!==id);notify('Administrator removed.');return}if(['nextStage','prevStage','testOrg','activateOrg','ownerOverview'].includes(name)){auth(session.org,null,['owner']);if(name==='nextStage'){if(o.stage===3){required(o.admins.length&&o.locations.length,'Configure locations and an organisation administrator first.')}o.stage=Math.min(6,o.stage+1)}if(name==='prevStage')o.stage=Math.max(2,o.stage-1);if(name==='ownerOverview')page='dashboard';if(name==='testOrg'){let errors=validateOrg(o);o.tests.push({date:stamp(),result:errors.length?'Failed: '+errors.join(' '):'Passed configuration checks'});notify(errors.length?'Configuration test failed; review the messages.':'Configuration test passed.')}if(name==='activateOrg'){let errors=validateOrg(o);required(!errors.length,errors.join(' '));required(o.tests.at(-1)?.result==='Passed configuration checks','Run a passing configuration test before activation.');o.active=true;page='dashboard';notify('Organisation activated with its separate records.')}return}throw Error('Unsupported action.')}
