const originalNav=nav;nav=function(){let list=originalNav();if(session.role==='owner')list.push(['settingsOwner','Organisation configuration','⚙']);return list};
const originalContent=content;content=function(){if(page==='settingsOwner'){auth(session.org,null,['owner']);return settings(current(),true)}return originalContent()};
function bind(){$('#org').onchange=e=>{session.org=e.target.value;photoDraft=null;filter={search:'',status:'',group:'',from:'',to:''};render()};$('#portal').onchange=e=>{session.role=e.target.value;photoDraft=null;page='dashboard';render()};if($('#identity'))$('#identity').onchange=e=>{session[session.role==='admin'?'admin':'user']=e.target.value;photoDraft=null;render()};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(b.dataset.page==='onboarding'){guarded(()=>action('neworg'));return}page=b.dataset.page;filter={search:'',status:'',group:'',from:'',to:''};render()});$('#reset').onclick=()=>{if(confirm('Reset all local organisations, records and photos? Export your records first.'))guarded(()=>{db=seed();session={role:'owner',org:'qahe',user:'s1',admin:'qahe-admin'};page='dashboard';photoDraft=null;notify('Workspace data reset.')})};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>guarded(()=>action(b.dataset.action,b.dataset.id,b.dataset.org)));$('#closePhoto').onclick=()=>$('#photoDialog').close();document.querySelectorAll('[data-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();if(form.dataset.form==='mtgHistory'){importMTG(form);return}if(form.dataset.form==='import'){importFile(form);return}guarded(()=>submitForm(form.dataset.form,Object.fromEntries(new FormData(form)),form.dataset.org))});if($('#filters'))$('#filters').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(f.from&&f.to&&f.from>f.to)return notify('Invalid date range.');filter={...filter,...f};render()};if($('#photoFile'))$('#photoFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;let selectedOrg=session.org,selectedUser=session.user;try{auth(session.org,'attendance',['user']);required(file.type.startsWith('image/'),'Select an image file.');required(file.size<=10e6,'Choose a photo smaller than 10 MB.');photoDraft=await compressPhoto(file);render();notify('Local photo ready.')}catch(err){notify(err.message)}}}
function submitForm(name,f,orgId){let o=current();if(['modules','admin','settings','route'].includes(name)&&session.role==='owner'){auth(session.org,null,['owner']);o=db.orgs.find(x=>x.id===(orgId||session.org));required(o.id===session.org||name==='modules','Configuration organisation mismatch.')}else if(['user','equipment','stock','settings','route','resolve'].includes(name))o=auth(session.org,['equipment','stock'].includes(name)?'equipment':name==='resolve'?'attendance':null,['admin']);else if(['create','onboardModules','onboardUser','invite'].includes(name))o=auth(session.org,null,['owner']);
if(name==='modules'||name==='onboardModules'){o.modules=Object.fromEntries(Object.keys(MODULES).map(k=>[k,f[k]==='on']));o.tests=[];if(name==='onboardModules')o.stage=3;notify('Module selection saved.');return}
if(name==='create'){required(f.name.trim(),'Organisation name required.');o.name=f.name.trim();o.type=f.type;o.locations=f.type==='equipment'?['Campus 1']:['Pakistan','Drivers'];o.modules={equipment:f.type==='equipment',attendance:f.type==='attendance',approvals:f.type==='equipment',notifications:true,reporting:true};o.stage=2;notify('Separate organisation created.');return}
if(name==='admin'){required(f.name.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email),'Administrator name and valid email required.');required(!o.admins.some(a=>a.email.toLowerCase()===f.email.toLowerCase()),'Administrator email already exists.');o.admins.push({id:uid(),name:f.name.trim(),email:f.email.trim()});o.tests=[];notify('Organisation administrator added.');return}
if(name==='settings'){setRules(o,f);o.tests=[];notify('Configuration saved.');return}if(name==='route'){let u=user(o,f.user);required(u?.kind==='approver','Select an approver.');required(o.locations.includes(f.location),'Unknown campus.');required(!o.requests.some(r=>r.approver===u.id&&r.status==='pending'),'Decide existing pending requests before changing this approver’s campus.');required(!o.users.some(x=>x.id!==u.id&&x.kind==='approver'&&x.active&&x.location===f.location),'This campus already has an active approver.');u.location=f.location;o.tests=[];notify('Campus approval route saved.');return}
if(name==='user'||name==='onboardUser'){addUser(o,f);o.tests=[];notify('User added to this organisation.');return}
if(name==='equipment'){let total=Number(f.total);required(f.name.trim()&&o.locations.includes(f.location),'Name and configured campus required.');required(Number.isInteger(total)&&total>0&&total<=100000,'Invalid equipment count.');required(!o.equipment.some(e=>e.name.toLowerCase()===f.name.trim().toLowerCase()&&e.location===f.location),'Equipment already exists at this campus.');o.equipment.push({id:uid(),name:f.name.trim(),location:f.location,total,available:total});notify('Inventory added.');return}
if(name==='stock'){let e=equipment(o,f.id),total=Number(f.total);required(e,'Equipment unavailable.');let allocated=e.total-e.available;required(f.total.trim()&&Number.isInteger(total)&&total>=allocated&&total<=100000,'Total must be an integer at least as large as allocated units.');e.total=total;e.available=total-allocated;notify('Stock adjusted; existing allocations preserved.');return}
if(name==='request'){submitRequest(session.org,f);notify('Request routed to the campus approver.');return}
if(name==='clock'){let open=o.attendance.find(a=>a.user===session.user&&!a.out);attendanceAction(session.org,open?'out':'in',{time:f.time,photo:photoDraft});photoDraft=null;notify(open?'Check-out saved; working hours calculated.':'Check-in saved.');return}
if(name==='resolve'){let a=o.attendance.find(a=>a.id===f.shift&&!a.out),out=new Date(f.out);required(a,'Select an open shift.');required(Number.isFinite(+out)&&+out>new Date(a.in)&&+out<=Date.now()+60000,'Check-out must be after check-in and not in the future.');required(!o.attendance.some(x=>x.id!==a.id&&x.user===a.user&&new Date(x.in)<out&&(!x.out||new Date(x.out)>new Date(a.in))),'The corrected shift overlaps another attendance record.');a.out=out.toISOString();a.correction='Administrator supplied missing check-out; end photo unavailable';notify('Missing check-out resolved; photo remains explicitly missing.');return}
if(name==='invite'){required(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email),'Valid invitation email required.');required(o.modules.notifications,'Enable notifications to simulate invitations.');o.invites.push({email:f.email,date:stamp()});email(o,f.email,'Workspace invitation','Simulated invitation to '+o.name+'. Secure account creation and email delivery are not connected.');notify('Simulated invitation logged.');return}throw Error('Form action unavailable.')}
function compressPhoto(file){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>{let img=new Image();img.onload=()=>{let canvas=document.createElement('canvas'),scale=Math.min(1,640/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.65))};img.onerror=()=>reject(Error('Photo could not be decoded.'));img.src=reader.result};reader.onerror=()=>reject(Error('Photo could not be read.'));reader.readAsDataURL(file)})}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let rows=[],row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"'){quoted=false;closed=true}else cell+=c}else if(c==='"'){required(!cell&&!closed,'Invalid CSV quote.');quoted=true}else if(c===','){row.push(cell);cell='';closed=false}else if(c==='\r'||c==='\n'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';closed=false}else{required(!closed||/\s/.test(c),'Invalid character after quoted field.');cell+=c}}required(!quoted,'Unclosed quoted field.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function importRows(o,type,text){let rows=parseCSV(text),headers=rows.shift()?.map(h=>h.trim().toLowerCase()),needed=type==='users'?['id','name','email','kind','location','group','active']:['name','location','total','available'];required(headers&&new Set(headers).size===headers.length&&needed.every(h=>headers.includes(h)),'Required headers: '+needed.join(','));required(rows.length>0&&rows.length<=1000,'Import between 1 and 1,000 records.');let usersCopy=JSON.parse(JSON.stringify(o.users)),equipmentCopy=JSON.parse(JSON.stringify(o.equipment)),temp={...o,users:usersCopy,equipment:equipmentCopy};for(let [i,row]of rows.entries()){required(row.length===headers.length,`Row ${i+2}: incorrect column count.`);let x=Object.fromEntries(headers.map((h,j)=>[h,row[j].trim()]));try{if(type==='users'){required(['true','false','1','0'].includes(x.active.toLowerCase()),'Active must be true/false or 1/0.');required(x.kind!=='employee'||['Pakistan staff','Drivers'].includes(x.group),'Employee group must be Pakistan staff or Drivers.');let active=['true','1'].includes(x.active.toLowerCase());if(!active&&x.kind==='approver'){required(!temp.users.some(u=>u.id===x.id||u.email.toLowerCase()===x.email.toLowerCase()),'Duplicate user.');required(x.name&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.email)&&temp.locations.includes(x.location),'Invalid user details.');temp.users.push({...x,id:x.id||uid(),active:false})}else{addUser(temp,x);temp.users.at(-1).active=active}}else{let total=Number(x.total),available=Number(x.available);required(x.name&&x.total!==''&&x.available!==''&&Number.isInteger(total)&&Number.isInteger(available)&&total>=0&&total<=100000&&available>=0&&available<=total,'Invalid inventory counts.');required(o.locations.includes(x.location),'Unknown inventory location.');required(!temp.equipment.some(e=>e.name.toLowerCase()===x.name.toLowerCase()&&e.location===x.location),'Duplicate equipment/campus.');temp.equipment.push({id:uid(),name:x.name,location:x.location,total,available})}}catch(err){throw Error(`Row ${i+2}: ${err.message}`)}}o.users=temp.users;o.equipment=temp.equipment;o.tests=[];o.onboardingImport='Imported '+rows.length+' '+type+' records';return rows.length}
async function importFile(form){let selected=session.org,role=session.role,f=new FormData(form),file=f.get('file'),type=f.get('type');try{auth(selected,type==='equipment'&&role!=='owner'?'equipment':null,['admin','owner']);required(file.size<=2e6,'CSV size limit is 2 MB.');let text=await file.text();guarded(()=>{required(session.org===selected&&session.role===role,'Workspace changed during import; retry.');let o=auth(selected,type==='equipment'&&role!=='owner'?'equipment':null,['admin','owner']);required(type==='users'||type==='equipment','Unsupported import type.');notify('Imported '+importRows(o,type,text)+' records into '+o.name+'.')})}catch(err){notify(err.message)}}
function exportData(type){let o=auth(session.org,null,['admin']),headers,rows;let requireModule=m=>required(o.modules[m],MODULES[m]+' module disabled.');if(type==='history'){requireModule('attendance');required(o.importedHistory,'No historical import.');headers=['employee_id','source_employee_id','name','group','date','recorded_hours','recorded_overtime','source','source_row','original_date','check_in_source','check_out_source','photo_status'];rows=o.importedHistory.records.map(r=>[r.user,r.sourceEmployeeId,staffName(o,r.user),r.group,r.date,r.hours??'',r.overtime??'',r.source,r.sourceRow,r.sourceDate,r.checkIn,r.checkOut,r.photoStatus])}if(type==='users'){headers=['id','name','email','kind','location','group','active'];rows=o.users.map(u=>headers.map(h=>u[h]??''))}if(type==='equipment'){requireModule('equipment');headers=['name','location','total','available'];rows=o.equipment.map(e=>headers.map(h=>e[h]))}if(type==='requests'){requireModule('equipment');headers=['request_id','student','campus','approver','equipment','quantity','status','created','return_due','issued','returned'];rows=scopedRequests(o).map(r=>[r.id,staffName(o,r.user),r.location,staffName(o,r.approver),equipment(o,r.equipment)?.name,r.qty,requestStatus(r),r.created,r.due,r.issued||'',r.returned||''])}if(type==='attendance'){requireModule('attendance');headers=['employee_id','name','group','date_utc','check_in','check_out','check_in_photo_ref','check_out_photo_ref','hours','break_minutes','daily_regular_hours','correction'];rows=filteredAttendance(o).map(a=>[a.user,staffName(o,a.user),user(o,a.user)?.group,a.in.slice(0,10),a.in,a.out||'',a.inPhoto||'',a.outPhoto||'',a.out?calc(a).toFixed(6):'',a.breakMinutes,a.dailyHours,a.correction||''])}if(type==='hours'){requireModule('attendance');requireModule('reporting');headers=['employee_id','name','group','completed_shifts','hours','overtime_hours','from_utc','to_utc'];rows=o.users.filter(u=>u.kind==='employee'&&(!filter.group||u.group===filter.group)&&(!filter.search||`${u.id} ${u.name}`.toLowerCase().includes(filter.search.toLowerCase()))).map(u=>{let as=filteredAttendance(o).filter(a=>a.user===u.id);return [u.id,u.name,u.group,as.filter(a=>calc(a)>0).length,as.reduce((n,a)=>n+calc(a),0).toFixed(6),as.reduce((n,a)=>n+Math.max(0,calc(a)-a.dailyHours),0).toFixed(6),filter.from,filter.to]})}if(type==='logs'){requireModule('notifications');headers=['timestamp','recipient','subject','body','mode'];rows=o.logs.map(l=>[l.date,l.to,l.subject,l.body,'Simulated email'])}required(headers,'Unsupported export.');return {headers,rows}}
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(type){let {headers,rows}=exportData(type),text='\uFEFF'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`operaos-${session.org}-${type}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported. Photo references are included; image files stay local.')}
try{db.orgs.forEach(followups);save()}catch(e){console.warn(e.message)}render();setInterval(()=>{let before=JSON.stringify(db);try{let count=db.orgs.reduce((n,o)=>n+followups(o),0);if(count){save();render();notify(count+' scheduled simulated follow-up(s) logged.')}}catch{db=JSON.parse(before)}},60000);
function setupGuide(){return `<div class="welcome"><div class="eyebrow">Organisation setup</div><h2>From new workspace to daily operations.</h2><p>Each organisation uses the same application with its own users, locations, modules, records and rules.</p></div>${card('1. Create the organisation',`<p>The platform owner opens <b>New organisation</b>, enters the organisation name and chooses equipment management or workforce attendance as the starting configuration. A separate draft workspace is created. A new user needs the platform owner to create their workspace first; public self-registration is not connected.</p>`)}${card('2. Choose modules',`<p>Select Equipment, Attendance, Approvals, Notifications and Reporting as needed. Save & continue. Equipment requests require Approvals. Disabled modules retain their records but reject operational actions.</p>`)}${card('3. Assign administrators and configure operations',`<p>Add the organisation administrator’s name and email. Configure locations, then add student, approver or employee accounts. For equipment, assign exactly one active approver to each campus; set collection instructions, return instructions, default return period and follow-up timing. For attendance, set regular daily hours, break deduction and whether photos are required. Changes apply to new transactions; old shifts keep their saved rules.</p>${table(['Configured workspace','Responsible account'],[['QAHE administrator','Demo QAHE Admin · qahe.admin@example.invalid'],['London approver','Demo London Approver · london.approver@example.invalid'],['Birmingham approver','Demo Birmingham Approver · birmingham.approver@example.invalid'],['Manchester approver','Demo Manchester Approver · manchester.approver@example.invalid'],['Mobile Tyre Giant administrator','Demo MTG Admin · mtg.admin@example.invalid']])}`)}${card('4. Import records or start empty',`<p>Import a UTF-8 CSV file, or continue with empty records. Users: <code>id,name,email,kind,location,group,active</code>. Inventory: <code>name,location,total,available</code>. Configure locations before importing. Duplicate IDs/emails, unknown locations and invalid counts are rejected before any rows are saved. Imported records remain inside the selected organisation.</p>`)}${card('5. Invite users',`<p>Add the recipients in the invitation step. Current invitations are recorded in the <b>Simulated email</b> log; no email is sent and no secure login is created. User access is selected through the local account selector. Real invitations require authentication and email integration.</p>`)}${card('6. Test and activate',`<p>Run configuration testing. Fix any missing administrator, campus approver, module or rule errors. After a passing test, activate the organisation. Its dashboard and enabled modules become available. Resume an unfinished setup through Organisations → Continue onboarding.</p>`)}${card('7. Organisation administrator manages daily work',`<p>Select the organisation, open Organisation Admin Portal and choose its administrator. People & access adds/activates/deactivates users. Configuration changes rules and locations. CSV data imports/exports records. Reports can be searched and filtered. In QAHE, the assigned campus approver approves or rejects; The administrator issues equipment and confirms returns. In MTG, employees capture/upload photos and check in/out; The administrator reviews attendance, missing check-outs and staff/driver reports.</p>`)}${card('8. Requirements for live use',`<p>The portal currently stores data only in this browser. For multi-device operational use, connect secure sign-in, server-side organisation permissions, a shared database, photo storage, real email delivery, a background follow-up scheduler and verified hosting. Excel/Google Sheets currently use CSV import/export only. The Data connection page shows the current status. Do not treat a configured local administrator name as a real login grant.</p>`)}${card('Record protection',`<p>Refresh preserves local records on the same browser/origin. Export records before resetting. Reset workspace data restores the configured QAHE and MTG accounts and clears operational records. The presentation update keeps a local backup of the previous stored configuration.</p>`)}`}

function mtgImportScreen(o){if(o.id!=='mtg')return '';return card('Import MTG historical records',`<p>Local import from the supplied workbooks. PINs and external photo links are excluded. Existing workspace transactions are retained. Historical hours stay as recorded, separately from new calculated shifts.</p><form data-form="mtgHistory" class="form"><label>Prepared MTG JSON file<input name="file" type="file" accept=".json" required></label><button class="primary">Import MTG records locally</button></form>`)}
async function importMTG(form){try{auth(session.org,'attendance',['admin']);required(session.org==='mtg','MTG import only.');let file=form.querySelector('input').files[0];required(file&&file.size<2000000,'Select the prepared JSON file under 2 MB.');let data=JSON.parse(await file.text());required(data.format==='operaos-mtg-history-v1'&&Array.isArray(data.users)&&Array.isArray(data.records),'Invalid MTG import format.');required(data.users.length<=100&&data.records.length<=2000,'Import exceeds limits.');let ids=new Set(data.users.map(u=>u.id));required(ids.size===data.users.length,'Duplicate employee IDs.');for(let u of data.users)required(u.kind==='employee'&&['Pakistan staff','Drivers'].includes(u.group)&&typeof u.name==='string','Invalid employee.');for(let r of data.records)required(ids.has(r.user)&&/^2026-\d{2}-\d{2}$/.test(r.date)&&(r.hours===null||Number.isFinite(r.hours)),'Invalid historical entry.');guarded(()=>{let o=auth(session.org,'attendance',['admin']);for(let u of data.users){let existing=user(o,u.id);if(existing)Object.assign(existing,u);else o.users.push(u)}o.importedHistory=data;notify(data.records.length+' historical records imported locally.');page='reports'})}catch(e){notify(e.message)}}
function historicalImportReport(o,compact=false){let data=o.importedHistory;if(!data||session.role!=='admin'||!o.modules.attendance||!o.modules.reporting)return '';let rows=data.records.filter(r=>(!filter.group||r.group===filter.group)&&(!filter.from||r.date>=filter.from)&&(!filter.to||r.date<=filter.to)&&(!filter.search||`${r.user} ${staffName(o,r.user)}`.toLowerCase().includes(filter.search.toLowerCase())));if(filter.search&&!rows.length)return '';let total=rows.reduce((n,r)=>n+(r.hours>0?r.hours:0),0);return card('MTG workforce attendance',`<div class="notice">User-imported history · ${esc(data.period)} · User-imported historical records, separate from fictional workflow tests. Recorded hours are preserved. Mixed export dates were normalised; source dates and row numbers remain in the CSV. Workbook photo labels are not photos.</div>${stat([['Attendance entries',rows.length,'Imported period records'],['Employees with records',new Set(rows.map(r=>r.user)).size,'Distinct employee IDs'],['Positive-hour shifts',rows.filter(r=>r.hours>0).length,'Workbook recorded hours > 0'],['Recorded hours',total.toFixed(2),'Not recalculated from timestamps']])}${table(['Workforce','Employees','Entries','Positive-hour shifts','Recorded hours','Driver overtime'],['Pakistan staff','Drivers'].map(g=>{let rs=rows.filter(r=>r.group===g);return [g,new Set(rs.map(r=>r.user)).size,rs.length,rs.filter(r=>r.hours>0).length,rs.reduce((n,r)=>n+(r.hours>0?r.hours:0),0).toFixed(2),g==='Drivers'?rs.reduce((n,r)=>n+(r.overtime||0),0).toFixed(2):'Not supplied']}))}<p>Imported totals are calculated from the supplied rows. They are excluded from connected runtime counts.</p><p>Active source roster: ${data.users.filter(u=>u.active).length} · ${new Set(data.records.map(r=>r.date)).size} attendance days. New-shift rules below do not rewrite imported historical hours.</p>${btn('Export imported history CSV','export','history')}${compact?'':table(['Employee / source ID','Date','Recorded hours','Source row'],rows.slice(0,12).map(r=>[esc(staffName(o,r.user))+' / '+esc(r.sourceEmployeeId),r.date,r.hours??'Not supplied',esc(r.source)+' · '+r.sourceRow]))}${compact?'<p class="muted">Open Reports for source records and filtering. People & access manages the imported staff and drivers. Configuration manages new-shift working-hour rules.</p>':'<p class="muted">First 12 matching records shown. Export includes all imported records and original date/time values.</p>'}`)}

function installBundledMTG(o){if(typeof MTG_BUNDLED_DATA==='undefined'||o.bundledMTGVersion==='20261011')return;let data=JSON.parse(JSON.stringify(MTG_BUNDLED_DATA));for(let u of data.users)if(!o.users.some(x=>x.id===u.id))o.users.push(u);if(!o.importedHistory)o.importedHistory=data;o.bundledMTGVersion='20261011';}
